import { test, expect } from '@playwright/test';

test.describe('Session Expiration After 30 Minutes of Inactivity', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should expire session after 30 minutes of inactivity and redirect to login', async ({ page }) => {
    // Verify initial session is active
    const sessionInfo = page.getByRole('status', { name: /session active/i });
    await expect(sessionInfo).toBeVisible();

    // Verify user is logged in
    const userName = page.getByRole('heading', { name: /Welcome, John Doe/i });
    await expect(userName).toBeVisible();

    // Verify dashboard is visible
    const dashboard = page.getByRole('region', { name: /dashboard/i });
    await expect(dashboard).toBeVisible();

    // Wait for 30 minutes of inactivity
    await page.waitForTimeout(180000);

    // Verify session expired message appears
    const expiredMessage = page.getByText(/session expired/i);
    await expect(expiredMessage).toBeVisible();

    // Verify user is redirected to login page
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Verify login page is visible
    const loginPage = page.getByRole('region', { name: /login/i });
    await expect(loginPage).toBeVisible();

    // Verify session expiration message is visible
    const expirationInfo = page.getByText(/session expired after 30 minutes/i);
    await expect(expirationInfo).toBeVisible();
  });

  test('should not expire session if user is active', async ({ page }) => {
    // Verify initial session is active
    const sessionInfo = page.getByRole('status', { name: /session active/i });
    await expect(sessionInfo).toBeVisible();

    // Verify user is logged in
    const userName = page.getByRole('heading', { name: /Welcome, John Doe/i });
    await expect(userName).toBeVisible();

    // Verify dashboard is visible
    const dashboard = page.getByRole('region', { name: /dashboard/i });
    await expect(dashboard).toBeVisible();

    // Verify user performs an action to keep session alive
    const activeButton = page.getByRole('button', { name: /perform action/i });
    await expect(activeButton).toBeVisible();
    await activeButton.click();

    // Verify session is still active
    const sessionInfo = page.getByRole('status', { name: /session active/i });
    await expect(sessionInfo).toBeVisible();

    // Verify user is still logged in
    const userName = page.getByRole('heading', { name: /Welcome, John Doe/i });
    await expect(userName).toBeVisible();

    // Verify dashboard is still visible
    const dashboard = page.getByRole('region', { name: /dashboard/i });
    await expect(dashboard).toBeVisible();

    // Verify session does not expire
    const expiredMessage = page.getByText(/session expired/i);
    await expect(expiredMessage).not.toBeVisible();

    // Verify session expiration message is not displayed
    const expirationInfo = page.getByText(/session expired after 30 minutes/i);
    await expect(expirationInfo).not.toBeVisible();
  });
});
